exec(compile('"""Conservative extraction repair v1, frozen for baseline and iteration 1.\nNo gold labels, LLM calls, mathematical solving, or generated-code repairs.\nRetains existing predictions except PopQA\'s known whole-response fallback.\n"""\nimport json\nimport re\n\nMC = {\'arc_challenge\', \'openbookqa\', \'mmlu\', \'gpqa\'}\nCODE = {\'humanevalplus\', \'mbppplus\', \'livecodebench_v3\', \'code_contests\'}\nENABLED = MC | CODE | {\'math_hard\', \'math\', \'bbh\', \'agieval\', \'popqa\'}\n\n\ndef explicit(text):\n    """Only an explicit final field at the end of the response."""\n    text = re.sub(r\'\\*\\*((?:(?:the |final )?answer|prediction)\\s*:?)\\*\\*\', r\'\\1\', text, flags=re.I)\n    patterns = [\n        r\'(?i)(?<![\\w])prediction[ \\t]*:[ \\t]*(?:\\r?\\n[ \\t]*)?([^\\r\\n]+)\',\n        r\'(?im)^[ \\t]*(?:the[ \\t]+)?(?:final[ \\t]+)?answer[ \\t]*(?:is[ \\t]*[:=]?|[:=])[ \\t]*(?:\\r?\\n[ \\t]*)?([^\\r\\n]+)\',\n    ]\n    for pattern in patterns:\n        matches = list(re.finditer(pattern, text))\n        if matches and not text[matches[-1].end():].strip():\n            return matches[-1].group(1).strip().strip(\'`\')\n    return \'\'\n\n\ndef option(candidate, letters):\n    candidate = candidate.strip().strip(\'*\').strip()\n    m = re.fullmatch(r\'\\(?([\' + letters + r\'])\\)?[.]?\', candidate, re.I)\n    if m:\n        return m.group(1).upper()\n    # Final fields may repeat option text, e.g. (B)300 or D. 8. Refuse\n    # conflicting option identifiers; never choose a letter from prose words.\n    m = re.match(r\'^(?:\\(([\' + letters + r\'])\\)|([\' + letters + r\'])[.)][ \\t]+)(.+)$\', candidate, re.I)\n    if m:\n        tail = m.group(3)\n        if re.search(r\'\\([A-Z]\\)|\\b(?:or|and)\\s+[A-Z]\\b|\\b[A-Z][.)]\\s\', tail):\n            return \'\'\n        return (m.group(1) or m.group(2)).upper()\n    return \'\'\n\n\ndef repair(benchmark, raw, original, *, finish_reason=\'\', options=\'\'):\n    raw, original = str(raw or \'\'), str(original or \'\')\n    if benchmark not in ENABLED:\n        return original, \'unchanged_benchmark\'\n    if benchmark in CODE:\n        if original.strip():\n            return original, \'original\'\n        # The existing restricted worker checks syntax and runs original tests.\n        # Passing raw text does not imply that the program is valid or correct.\n        candidate = re.sub(r\'<think>.*?</think>\', \'\', raw, flags=re.S | re.I).strip(\'\\r\\n\')\n        return (candidate, \'raw_code_to_original_worker\') if candidate.strip() else (original, \'empty\')\n    if original.strip() and benchmark != \'popqa\':\n        return original, \'original\'\n    if finish_reason == \'length\':\n        return original, \'truncated_no_fallback\'\n    candidate = explicit(raw)\n    is_mc = benchmark in MC\n    letters = \'ABCD\'\n    if benchmark == \'agieval\':\n        try:\n            choices = json.loads(options) if isinstance(options, str) else options\n        except (ValueError, TypeError):\n            choices = []\n        is_mc = isinstance(choices, list) and bool(choices)\n        letters = \'ABCDEFGHIJKLMNOPQRSTUVWXYZ\'[:len(choices)] if is_mc else \'\'\n    if is_mc:\n        selected = option(candidate, letters) if candidate else \'\'\n        if selected:\n            return selected, \'explicit_final_choice\'\n        # A plain final sentence, including "the correct answer is D."\n        clean = raw.replace(\'**\', \'\')\n        m = re.search(r\'(?i)\\b(?:the\\s+)?(?:correct\\s+|final\\s+)?answer\\s+(?:is\\s*)[:=]?\\s*\\(?([\' + letters + r\'])\\)?[.!]?\\s*$\', clean)\n        if m:\n            return m.group(1).upper(), \'final_answer_letter\'\n        if benchmark == \'agieval\':\n            selected = option(clean.strip(), letters)\n            if selected:\n                return selected, \'bare_choice\'\n            # AGIEval answers sometimes state a selected option in prose.\n            # Only accept one unique parenthesized option throughout the\n            # answer, with no echoed question/options or competing letters.\n            if clean.lstrip().startswith(\'complete_prediction:\') and \'Output columns:\' not in clean and \'\\nChoices:\' not in clean and \'\\nOptions:\' not in clean:\n                found = set(re.findall(r\'\\(([\' + letters + r\'])\\)\', clean))\n                if len(found) == 1:\n                    return found.pop(), \'unique_option_in_response\'\n        return original, \'unresolved\'\n    if candidate:\n        if benchmark == \'popqa\':\n            candidate = candidate.strip(\' .\\"\\\'\')\n        return candidate, \'explicit_final_answer\'\n    if benchmark == \'agieval\':\n        bare = raw.strip()\n        if \'\\n\' not in bare and len(bare) <= 100 and re.fullmatch(r\'[\\dA-Z+\\-*/().,\\s]+|(?:sin|cos|tan)\\s*[\\d.]+[°]?\', bare):\n            return bare, \'bare_math_answer\'\n    return original, \'unresolved\'\n',__file__,"exec"),m.__dict__)
