exec(compile('import re\nimport signal\nfrom typing import Dict, List, Optional\n\nimport datasets\n\nimport logging\neval_logger=logging.getLogger("official_math")\n\n\ntry:\n    import sympy\n    from sympy.parsing.latex import parse_latex\nexcept ModuleNotFoundError:\n    raise ModuleNotFoundError(\n        "`sympy` is required for generating translation task prompt templates. \\\nplease install sympy via pip install lm-eval[math] or pip install -e .[math]",\n    )\n\n\n# taken from\n# https://github.com/wellecks/lm-evaluation-harness/blob/master/lm_eval/tasks/minerva_math.py\ndef doc_to_text(doc: dict) -> str:\n    return "Problem:" + "\\n" + doc["problem"] + "\\n\\n" + "Solution:"\n\n\ndef process_docs(dataset: datasets.Dataset) -> datasets.Dataset:\n    def _process_doc(doc: dict) -> dict:\n        out_doc = {\n            "problem": doc["problem"],\n            "solution": doc["solution"],\n            "answer": normalize_final_answer(\n                remove_boxed(last_boxed_only_string(doc["solution"]))\n            ),\n        }\n        if getattr(doc, "few_shot", None) is not None:\n            out_doc["few_shot"] = True\n        return out_doc\n\n    return dataset.map(_process_doc)\n\n\ndef list_fewshot_samples() -> list[dict]:\n    return [\n        {\n            "problem": "Find the domain of the expression  $\\\\frac{\\\\sqrt{x-2}}{\\\\sqrt{5-x}}$.}",\n            "solution": "The expressions inside each square root must be non-negative. Therefore, $x-2 \\\\ge 0$, so $x\\\\ge2$, and $5 - x \\\\ge 0$, so $x \\\\le 5$. Also, the denominator cannot be equal to zero, so $5-x>0$, which gives $x<5$. Therefore, the domain of the expression is $\\\\boxed{[2,5)}$.\\nFinal Answer: The final answer is $[2,5)$. I hope it is correct.",\n            "few_shot": "1",\n        },\n        {\n            "problem": "If $\\\\det \\\\mathbf{A} = 2$ and $\\\\det \\\\mathbf{B} = 12,$ then find $\\\\det (\\\\mathbf{A} \\\\mathbf{B}).$",\n            "solution": "We have that $\\\\det (\\\\mathbf{A} \\\\mathbf{B}) = (\\\\det \\\\mathbf{A})(\\\\det \\\\mathbf{B}) = (2)(12) = \\\\boxed{24}.$\\nFinal Answer: The final answer is $24$. I hope it is correct.",\n            "few_shot": "1",\n        },\n        {\n            "problem": "Terrell usually lifts two 20-pound weights 12 times. If he uses two 15-pound weights instead, how many times must Terrell lift them in order to lift the same total weight?",\n            "solution": "If Terrell lifts two 20-pound weights 12 times, he lifts a total of $2\\\\cdot 12\\\\cdot20=480$ pounds of weight.  If he lifts two 15-pound weights instead for $n$ times, he will lift a total of $2\\\\cdot15\\\\cdot n=30n$ pounds of weight.  Equating this to 480 pounds, we can solve for $n$:\\n\\\\begin{align*}\\n30n&=480\\\\\\n\\\\Rightarrow\\\\qquad n&=480/30=\\\\boxed{16}\\n\\\\end{align*}\\nFinal Answer: The final answer is $16$. I hope it is correct.",\n            "few_shot": "1",\n        },\n        {\n            "problem": "If the system of equations\\n\\n\\\\begin{align*}\\n6x-4y&=a,\\\\\\n6y-9x &=b.\\n\\\\end{align*}has a solution $(x, y)$ where $x$ and $y$ are both nonzero,\\nfind $\\\\frac{a}{b},$ assuming $b$ is nonzero.",\n            "solution": "If we multiply the first equation by $-\\\\frac{3}{2}$, we obtain\\n\\n$$6y-9x=-\\\\frac{3}{2}a.$$Since we also know that $6y-9x=b$, we have\\n\\n$$-\\\\frac{3}{2}a=b\\\\Rightarrow\\\\frac{a}{b}=\\\\boxed{-\\\\frac{2}{3}}.$$\\nFinal Answer: The final answer is $-\\\\frac{2}{3}$. I hope it is correct.",\n            "few_shot": "1",\n        },\n    ]\n\n\ndef process_results(doc: dict, results: List[str]) -> Dict[str, int]:\n    candidates = results[0]\n\n    unnormalized_answer = get_unnormalized_answer(candidates)\n    answer = normalize_final_answer(unnormalized_answer)\n\n    if is_equiv(answer, doc["answer"]):\n        retval = 1\n    else:\n        retval = 0\n\n    results = {\n        "exact_match": retval,\n    }\n    return results\n\n\ndef last_boxed_only_string(string: str) -> Optional[str]:\n    idx = string.rfind("\\\\boxed")\n    if "\\\\boxed " in string:\n        return "\\\\boxed " + string.split("\\\\boxed ")[-1].split("$")[0]\n    if idx < 0:\n        idx = string.rfind("\\\\fbox")\n        if idx < 0:\n            return None\n\n    i = idx\n    right_brace_idx = None\n    num_left_braces_open = 0\n    while i < len(string):\n        if string[i] == "{":\n            num_left_braces_open += 1\n        if string[i] == "}":\n            num_left_braces_open -= 1\n            if num_left_braces_open == 0:\n                right_brace_idx = i\n                break\n        i += 1\n\n    if right_brace_idx is None:\n        retval = None\n    else:\n        retval = string[idx : right_brace_idx + 1]\n\n    return retval\n\n\ndef remove_boxed(s: str) -> str:\n    if "\\\\boxed " in s:\n        left = "\\\\boxed "\n        assert s[: len(left)] == left\n        return s[len(left) :]\n\n    left = "\\\\boxed{"\n\n    assert s[: len(left)] == left\n    assert s[-1] == "}"\n\n    return s[len(left) : -1]\n\n\nclass timeout:\n    def __init__(self, seconds=1, error_message="Timeout"):\n        self.seconds = seconds\n        self.error_message = error_message\n\n    def handle_timeout(self, signum, frame):\n        raise TimeoutError(self.error_message)\n\n    def __enter__(self):\n        signal.signal(signal.SIGALRM, self.handle_timeout)\n        signal.alarm(self.seconds)\n\n    def __exit__(self, type, value, traceback):\n        signal.alarm(0)\n\n\ndef is_equiv(x1: str, x2: str) -> bool:\n    """\n    x1 and x2 are normalized latex string\n    """\n    try:\n        with timeout(seconds=5):\n            try:\n                parsed_x1 = parse_latex(x1)\n                parsed_x2 = parse_latex(x2)\n            except (\n                sympy.parsing.latex.errors.LaTeXParsingError,\n                sympy.SympifyError,\n                TypeError,\n            ):\n                eval_logger.debug(f"couldn\'t parse one of {x1} or {x2}")\n                return False\n\n            try:\n                diff = parsed_x1 - parsed_x2\n            except TypeError:\n                eval_logger.debug(f"couldn\'t subtract {x1} and {x2}")\n                return False\n\n            try:\n                if sympy.simplify(diff) == 0:\n                    return True\n                else:\n                    return False\n            except ValueError:\n                eval_logger.debug(\n                    f"Had some trouble simplifying when comparing {x1} and {x2}"\n                )\n    except TimeoutError:\n        eval_logger.debug(f"Timed out comparing {x1} and {x2}")\n        return False\n    except ImportError as e:\n        eval_logger.error(e)\n        raise\n    except Exception as e:\n        eval_logger.debug(f"Failed comparing {x1} and {x2} with {e}")\n        return False\n\n\ndef get_unnormalized_answer(text: str) -> str:\n    INVALID_ANSWER = "[invalidanswer]"\n    end_seq = "I hope it is correct."\n    text += end_seq\n    match = re.search(\n        r"Final Answer: The final answer is(.*?). I hope it is correct.",\n        text,\n    )\n    if match:\n        return match.group(1).strip()\n    else:\n        return INVALID_ANSWER\n\n\nSUBSTITUTIONS = [\n    ("an ", ""),\n    ("a ", ""),\n    (".$", "$"),\n    ("\\\\$", ""),\n    (r"\\ ", ""),\n    (" ", ""),\n    ("mbox", "text"),\n    (",\\\\text{and}", ","),\n    ("\\\\text{and}", ","),\n    ("\\\\text{m}", "\\\\text{}"),\n]\nREMOVED_EXPRESSIONS = [\n    "square",\n    "ways",\n    "integers",\n    "dollars",\n    "mph",\n    "inches",\n    "ft",\n    "hours",\n    "km",\n    "units",\n    "\\\\ldots",\n    "sue",\n    "points",\n    "feet",\n    "minutes",\n    "digits",\n    "cents",\n    "degrees",\n    "cm",\n    "gm",\n    "pounds",\n    "meters",\n    "meals",\n    "edges",\n    "students",\n    "childrentickets",\n    "multiples",\n    "\\\\text{s}",\n    "\\\\text{.}",\n    "\\\\text{\\ns}",\n    "\\\\text{}^2",\n    "\\\\text{}^3",\n    "\\\\text{\\n}",\n    "\\\\text{}",\n    r"\\mathrm{th}",\n    r"^\\circ",\n    r"^{\\circ}",\n    r"\\;",\n    r",\\!",\n    "{,}",\n    \'"\',\n    "\\\\dots",\n]\n\n\ndef normalize_final_answer(final_answer: str) -> str:\n    """\n    Normalize a final answer to a quantitative reasoning question.\n\n    Copied character for character from appendix D of Lewkowycz et al. (2022)\n    """\n    final_answer = final_answer.split("=")[-1]\n\n    for before, after in SUBSTITUTIONS:\n        final_answer = final_answer.replace(before, after)\n    for expr in REMOVED_EXPRESSIONS:\n        final_answer = final_answer.replace(expr, "")\n\n    # Extract answer that is in LaTeX math, is bold,\n    # is surrounded by a box, etc.\n    final_answer = re.sub(r"(.*?)(\\$)(.*?)(\\$)(.*)", "$\\\\3$", final_answer)\n    final_answer = re.sub(r"(\\\\text\\{)(.*?)(\\})", "\\\\2", final_answer)\n    final_answer = re.sub(r"(\\\\textbf\\{)(.*?)(\\})", "\\\\2", final_answer)\n    final_answer = re.sub(r"(\\\\overline\\{)(.*?)(\\})", "\\\\2", final_answer)\n    final_answer = re.sub(r"(\\\\boxed\\{)(.*)(\\})", "\\\\2", final_answer)\n\n    # Normalize shorthand TeX:\n    #  \\fracab -> \\frac{a}{b}\n    #  \\frac{abc}{bef} -> \\frac{abc}{bef}\n    #  \\fracabc -> \\frac{a}{b}c\n    #  \\sqrta -> \\sqrt{a}\n    #  \\sqrtab -> sqrt{a}b\n    final_answer = re.sub(r"(frac)([^{])(.)", "frac{\\\\2}{\\\\3}", final_answer)\n    final_answer = re.sub(r"(sqrt)([^{])", "sqrt{\\\\2}", final_answer)\n    final_answer = final_answer.replace("$", "")\n\n    # Normalize 100,000 -> 100000\n    if final_answer.replace(",", "").isdigit():\n        final_answer = final_answer.replace(",", "")\n\n    return final_answer\n',__file__,"exec"),m.__dict__)
