exec(compile('import dataclasses\nfrom typing import Dict, Optional, Union\n\nimport logging\neval_logger=logging.getLogger("official_ifeval")\n\nfrom ifbench import instructions_registry\n\n\n@dataclasses.dataclass\nclass InputExample:\n    key: int\n    instruction_id_list: list[str]\n    prompt: str\n    kwargs: list[Dict[str, Optional[Union[str, int]]]]\n\n\n@dataclasses.dataclass\nclass OutputExample:\n    instruction_id_list: list[str]\n    prompt: str\n    response: str\n    follow_all_instructions: bool\n    follow_instruction_list: list[bool]\n\n\ndef test_instruction_following_strict(\n    inp,\n    response,\n):\n    """Tests response to see if instructions are followed."""\n    instruction_list = inp.instruction_id_list\n    is_following_list = []\n    for index, instruction_id in enumerate(instruction_list):\n        try:\n            instruction_cls = instructions_registry.INSTRUCTION_DICT[instruction_id]\n            instruction = instruction_cls(instruction_id)\n\n            # Remove None values from kwargs to avoid unexpected keyword argument errors in build_description method.\n            kwargs = {k: v for k, v in inp.kwargs[index].items() if v}\n            instruction.build_description(**kwargs)\n            args = instruction.get_instruction_args()\n            if args and "prompt" in args:\n                instruction.build_description(prompt=inp.prompt)\n\n            if response.strip() and instruction.check_following(response):\n                is_following_list.append(True)\n            else:\n                is_following_list.append(False)\n        except Exception as e:\n            is_following_list.append(False)\n            eval_logger.warning(f"Error for strict test in prompt {inp.prompt} with response {response}: {e}")\n            eval_logger.exception("Error occurred: %s", e)\n\n    return OutputExample(\n        instruction_id_list=inp.instruction_id_list,\n        prompt=inp.prompt,\n        response=response,\n        follow_all_instructions=all(is_following_list),\n        follow_instruction_list=is_following_list,\n    )\n\n\ndef test_instruction_following_loose(\n    inp,\n    response,\n):\n    """Tests response for an upper bound for following instructions."""\n    r = response.split("\\n")\n    response_remove_first = "\\n".join(r[1:]).strip()\n    response_remove_last = "\\n".join(r[:-1]).strip()\n    response_remove_both = "\\n".join(r[1:-1]).strip()\n    revised_response = response.replace("*", "")\n    revised_response_remove_first = response_remove_first.replace("*", "")\n    revised_response_remove_last = response_remove_last.replace("*", "")\n    revised_response_remove_both = response_remove_both.replace("*", "")\n    all_responses = [\n        response,\n        revised_response,\n        response_remove_first,\n        response_remove_last,\n        response_remove_both,\n        revised_response_remove_first,\n        revised_response_remove_last,\n        revised_response_remove_both,\n    ]\n    instruction_list = inp.instruction_id_list\n    is_following_list = []\n\n    for index, instruction_id in enumerate(instruction_list):\n        try:\n            instruction_cls = instructions_registry.INSTRUCTION_DICT[instruction_id]\n            instruction = instruction_cls(instruction_id)\n\n            # Remove None values from kwargs to avoid unexpected keyword argument errors in build_description method.\n            kwargs = {k: v for k, v in inp.kwargs[index].items() if v}\n            instruction.build_description(**kwargs)\n            args = instruction.get_instruction_args()\n            if args and "prompt" in args:\n                instruction.build_description(prompt=inp.prompt)\n\n            is_following = False\n            for r in all_responses:\n                if r.strip() and instruction.check_following(r):\n                    is_following = True\n                    break\n\n            is_following_list.append(is_following)\n        except Exception as e:\n            is_following_list.append(False)\n            eval_logger.warning(f"Error for loose test in prompt {inp.prompt} with response {response}")\n            eval_logger.exception("Error occurred: %s", e)\n\n    return OutputExample(\n        instruction_id_list=inp.instruction_id_list,\n        prompt=inp.prompt,\n        response=response,\n        follow_all_instructions=all(is_following_list),\n        follow_instruction_list=is_following_list,\n    )\n\n\ndef process_results(doc, results):\n    eval_logger.warning(\n        "This task is meant for chat-finetuned models, and may not give meaningful results for models other than `openai` or `anthropic` if `doc_to_text` in its YAML is not wrapped in the appropriate chat template string. This warning will be removed when chat templating support is added natively to local models"\n    )\n\n    inp = InputExample(\n        key=doc["key"],\n        instruction_id_list=doc["instruction_id_list"],\n        prompt=doc["prompt"],\n        kwargs=doc["kwargs"],\n    )\n    response = results[0]\n\n    out_strict = test_instruction_following_strict(inp, response)\n    out_loose = test_instruction_following_loose(inp, response)\n\n    return {\n        "prompt_level_strict_acc": out_strict.follow_all_instructions,\n        "inst_level_strict_acc": out_strict.follow_instruction_list,\n        "prompt_level_loose_acc": out_loose.follow_all_instructions,\n        "inst_level_loose_acc": out_loose.follow_instruction_list,\n    }\n\n\ndef agg_inst_level_acc(items):\n    flat_items = [item for sublist in items for item in sublist]\n    inst_level_acc = sum(flat_items) / len(flat_items)\n    return inst_level_acc',__file__,"exec"),m.__dict__)
