"""OLMES Task v5: use raw continuations and pinned official extraction/scoring methods."""
import csv,json,sys,collections,copy
from pathlib import Path
from statistics import mean
import v4_scoring as previous
import official_reference as ref
from official_exact_match import exact_match_hf_evaluate
CONFIGS=OFFICIAL_CONFIGS

def cfg(fragment):
 return copy.deepcopy(next(v for k,v in CONFIGS.items() if fragment in k))
def instance(cls,config):
 x=cls();x.task_config=config;return x
def metric_config(fragment):
 c=cfg(fragment);return copy.deepcopy(c.get('chat_overrides',{}).get('metric_kwargs',c.get('metric_kwargs',{})))
def exact(pred,gold,punctuation=False):
 return float(exact_match_hf_evaluate([str(pred)],[str(gold)],ignore_case=True,ignore_punctuation=punctuation)['exact_match'])
def score_one(benchmark,row,raw):
 if benchmark in {'math','aime_2024','aime_2025'}:
  task=instance(ref.OfficialMath,{'context_kwargs':{'use_cot':True,'cot_style':'plain'}})
  if benchmark=='math':gold=ref.normalize_final_answer(ref.remove_boxed(ref.last_boxed_only_string(row['solution'])))
  else:gold=str(row['answer'])
  values=task.process_results({'answer':gold},[raw])
  return float(values['exact_match_flex'])
 if benchmark=='omega':
  task=instance(ref.OfficialOmega,{'metric_kwargs':metric_config('omega')})
  extracted=task._extract_answer(raw)
  return exact(extracted['answer'],row['ground_truth'])
 if benchmark=='bbh':
  task=instance(ref.OfficialBBH,{'dataset_name':row['source_config'],'metric_kwargs':metric_config('bbh_')})
  return exact(task._extract_answer_regex(raw),row['target'])
 if benchmark in {'mmlu','agieval','gpqa'}:
  typ,key={'mmlu':(ref.OfficialMMLU,'mmlu_'),'agieval':(ref.OfficialAGI,'agi_eval_'),'gpqa':(ref.OfficialGPQA,'gpqa::')}[benchmark]
  task=instance(typ,{'metric_kwargs':metric_config(key)})
  gold=row['answer'] if benchmark=='gpqa' else row['label'] if benchmark=='agieval' else 'ABCD'[int(row['answer'])]
  return exact(task._extract_answer(raw)['answer'],gold,True)
 if benchmark=='popqa':
  return ref.OfficialPopQA().process_results({'alias':json.loads(row['possible_answers'])},[raw])['exact_match']
 raise ValueError('Unsupported benchmark '+benchmark)

def main():
 rows=previous.legacy.read_rows(sys.argv[2]);outputs=previous.legacy.read_rows(sys.argv[1]);previous.legacy.validate_alignment(rows,outputs)
 benchmark=outputs[0]['benchmark'];assert all(p['benchmark']==benchmark for p in outputs)
 if benchmark in {'ifeval','ifbench','zebralogic','alpacaeval'}:return previous.main()
 if not any(k in rows[0] and k in outputs[0] for k in ['zevo_id','id','key','task_id','question_id','unique_id']):raise ValueError('Missing shared row ID')
 # Raw response is authoritative: official extractors must see the full answer.
 raw=[p.get('complete_prediction') or p['prediction'] for p in outputs]
 values=[score_one(benchmark,r,p) for r,p in zip(rows,raw)]
 score,groups=previous.aggregate(benchmark,rows,values)
 metric='exact_match_flex' if benchmark in {'math','omega','aime_2024','aime_2025'} else 'exact_match'
 result={'score':score,metric:score,'benchmark':benchmark,'n_scored':len(rows),'n_total':len(rows),'n_excluded':0,'score_range':[0,1],'group_scores':groups,'protocol_revision':'olmo-task-v7','reference_revision':'5a51f502d463b8cdc4a2dcad7d7096c41ff1197e'}
 out=Path(sys.argv[3]);out.parent.mkdir(parents=True,exist_ok=True);out.write_text(json.dumps(result,indent=2)+'\n')
if __name__=='__main__':main()
